window.__BUNDLE__={"generatedAt":"2026-10-06T22:50:51.167617+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-29","archiveCutoff":"2021-10-07","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":296,"arxiv":1772,"total":2068},"freshness":{"latestPaperDate":"2026-10-06","latestPublishedDate":"2026-10-06","latestBatchCount":655,"newInLast24h":724,"newInLast48h":1107},"historyTotal":21173,"topicCounts":{"Multi-Agent":2525,"Evaluation":11463,"Planning":1626,"Memory":428,"Code Agent":839,"Interpretability":759,"Agentic RAG":1322,"Agentic Search":1704,"RL for LLM":1210,"Reasoning":5890,"Hallucination":1045,"Post-Training":2446,"Alignment":2814,"World Model":368,"Tool Use":1269,"Agent Safety":2437,"Computer Use":302,"Reflection":756,"VLM Training":1569,"LLM Training":2621,"Fine-tuning":3239,"Multimodal Agent":121,"Agent Framework":834,"Error Attribution":133,"Data Engine":422},"count":36,"recentTotal":3934,"archiveCount":0,"archiveTotal":17239,"sources":{"hf":123,"arxiv":3811,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"arxiv":"https://arxiv.org/abs/2610.05608","topics":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"authors":["Team Kandinsky","Julia Agafonova","Bulat Akhmatov","Mikhail Aksyutin","Grigorii Alekseenko","Anastasia Aliaskina","Olga Androsova","Vladimir Arkhipkin","Anna Averchenkova","Alexander Belykh","Serafima Bocharova","Sofiya Bogakovskaya","Anton Bukashkin","Mark Bulygin","Kirill Buzygin","Irina Cheremnykh","Kirill Chernyshev","Mikhail Chernyshov","Vladimir Chernyy","David Chikovani","Georgy Daniltsev","Denis Dimitrov","Anna Dmitrienko","Vladimir Dokholyan","Sergey Emelyanov","Dmitry Ermilov","Georgii Fedorov","Polina Gavrilova","Nikolai Gerasimenko","Aleksandr Gordeev","Andrey Inozemtsev","Andrei Ivaniuta","Alexander Ivanov","Mikhail Karaev","Anastasiia Kargapoltseva","Ivan Kirillov","Nikita Kiselev","Valeria Kobenko","Yury Kolabushin","Denis Koposov","Anatoly Korobov","Vladimir Korviakov","Kirill Kozlov","Denis Krzhivokolskiy","Konstantin Kuklev","Alexander Kunitsyn","Sergey Kuzin","Vladislav Lakhtionov","Alexey Letunovskiy","Maxim Litvinov","Alexander Lyulkov","Georgy Makarov","Kirill Malakhov","Egor Malykh","Mikhail Mamaev","Dmitrii Mikhailov","Polina Mikhailova","Ivan Mikheev","Elizaveta Muromtseva","Nikolai Nazarkin","Tatiana Nikulina","Lev Novitskiy","Stanislav Onuchin","Nikita Osterov","Denis Parkhomenko","Anatoliy Parpara","Vladimir Polovnikov","Konstantin Reznikov","Azat Saginbaev","Nikita Samsonov","Alexander Sentsov","Nikita Shaimov","Artem Sherstyuk","Andrey Shutkin","Egor Silvestrov","Bulat Suleimanov","Matvey Suprunov","Sergey Taranov","Irina Tolstykh","Tatiana Trofimuk","Ilya Trushkin","Aleksandra Tsybina","Olga Varlashina","Viacheslav Vasilev","Ilya Vasiliev","Eugeny Vilisov","Sergey Yakubson","Konstantin Zakharov"],"hfUrl":"https://huggingface.co/papers/2610.05608","id":"arxiv:2610.05608","date":"2026-10-06","source":"hf","title":"Kandinsky 6.0 Video: Foundation Models for Synchronized Video and Audio Generation","pdf":"https://arxiv.org/pdf/2610.05608.pdf","url":"https://arxiv.org/abs/2610.05608","submittedDate":"2026-10-04","upvotes":113,"tags":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-10-06","abstract":"We present Kandinsky 6.0 Video, a family of foundation diffusion models for synchronized text-to-audio-video generation, comprising Kandinsky 6.0 Video Lite (3B parameters) and Kandinsky 6.0 Video Pro (29B parameters). Both models generate 5-second video clips with synchronized 44 kHz audio, including lip-sync, in text-to-audio-video (T2AV) and image-to-audio-video (I2AV) modes; a built-in super-resolution model raises the output resolution to Full-HD (1920$\\times$1080). Building on the video generation capabilities of Kandinsky 5.0, Kandinsky 6.0 Video employs a dual-stream CrossDiT architecture that connects a pretrained video stream and a newly trained audio stream through bidirectional cross-attention for temporal and semantic alignment. Our continuous pretraining strategy first trains the audio stream from scratch on large-scale audio corpora and then trains both streams jointly on "},{"arxiv":"https://arxiv.org/abs/2610.04198","topics":["Evaluation"],"authors":["Liancheng Fang","Zhuowei Li","Youngeun Kim","Tianchen Zhao","Rajat Koner","Jiaye Wu","Linghan Xu","Xuanbai Chen","Xiang Xu","Zheng Zhang","Jakub Zablocki","Nishant Sankaran","Yifan Xing"],"hfUrl":"https://huggingface.co/papers/2610.04198","id":"arxiv:2610.04198","date":"2026-10-06","source":"hf","title":"ALoDLM: Adaptively Looped Diffusion Language Models","pdf":"https://arxiv.org/pdf/2610.04198.pdf","url":"https://arxiv.org/abs/2610.04198","submittedDate":"2026-10-03","upvotes":53,"tags":["Evaluation"],"announceDate":"2026-10-06","abstract":"Diffusion language models (DLMs) enable fast generation by predicting multiple tokens in parallel, but their practical adoption remains limited by a persistent quality gap relative to comparably sized autoregressive (AR) models. We attribute this gap to a computation-difficulty mismatch: within a partially observed sequence, some unknown tokens are easy to predict, while others require substantially more computation. Existing DLMs nevertheless apply uniform computational depth to all unknown positions at each denoising step. We introduce ALoDLM, which replaces uniform computation with token-adaptive latent recurrence. At each denoising step, ALoDLM iteratively refines latent representations and allocates computation according to token difficulty. Tokens ready to commit are fed back as discrete context, while unresolved tokens retain and further refine their latent states through addition"},{"arxiv":"https://arxiv.org/abs/2610.05162","topics":["Reasoning","Memory","Evaluation","Reflection"],"authors":["Ruqing Ning","Haibo Meng","Zhishang Xiang","Zerui Chen","Jinsong Su","Xin Wang","Qinggang Zhang"],"hfUrl":"https://huggingface.co/papers/2610.05162","id":"arxiv:2610.05162","date":"2026-10-06","source":"hf","title":"Memadapter: Counterfactual Adaptation Against Memory-induced Sycophancy","pdf":"https://arxiv.org/pdf/2610.05162.pdf","url":"https://arxiv.org/abs/2610.05162","submittedDate":"2026-10-04","upvotes":26,"tags":["Reasoning","Memory","Evaluation","Reflection"],"announceDate":"2026-10-06","abstract":"Long-term memory enables LLM-based agents to retain and reuse information across tasks and sessions, supporting personalization and long-horizon interactions. However, persistent memories can also induce sycophancy, causing agents to over-align with users' historical beliefs even when they are inaccurate, outdated, or inconsistent with objective evidence. Existing mitigation methods assume that memory-induced sycophancy originates from biased or incorrect memories and attempt to reduce this risk by filtering such memories at different stages of the memory pipeline. However, in the real world, objective and correct memories can still induce sycophancy, and the same memory can warrant different influence across different contexts. To this end, we propose MemAdapter, a novel framework that adaptively integrates retrieved memories to support objective and reliable reasoning. Specifically, Me"},{"arxiv":"https://arxiv.org/abs/2610.05303","topics":["Reasoning","Fine-tuning","Reflection"],"authors":["Haodong Lu","Dong Gong"],"hfUrl":"https://huggingface.co/papers/2610.05303","id":"arxiv:2610.05303","date":"2026-10-06","source":"hf","title":"ASCENT: Online Test-Time Training of Long-Horizon Agents via Self-Distillation of Verified Experience","pdf":"https://arxiv.org/pdf/2610.05303.pdf","url":"https://arxiv.org/abs/2610.05303","submittedDate":"2026-10-04","upvotes":13,"tags":["Reasoning","Fine-tuning","Reflection"],"announceDate":"2026-10-06","abstract":"A large language model (LLM) agent solves long-horizon tasks through many reasoning-action turns, with one verification signal at termination. Deployed agents face streams of related tasks, making their trajectories a natural resource for improvement. In-context adaptation agents store reflections, memories, or skills as text, so reuse depends on retrieving the right experience and on a frozen policy executing it. We study Online Agentic Test-Time Training (OaTTT), which trains the LLM's weights on its own execution trajectories during deployment. The agent executes each task once, in one pass over the stream, and the executed trajectory with its verification result is the only learning signal for weight updates that persist across tasks. Directly imitating or reinforcing the generated tokens of this single attempt destabilizes the policy. We introduce ASCENT (Agentic Self-distillation f"},{"arxiv":"https://arxiv.org/abs/2610.05870","topics":["Agent Safety"],"authors":["Sarim Hashmi","Abdelrahman Elsayed","Mohammed Talha Alam","Samuele Poppi","Nils Lukas"],"hfUrl":"https://huggingface.co/papers/2610.05870","id":"arxiv:2610.05870","date":"2026-10-06","source":"hf","title":"Certification of Real Images through Calibrated Content Authentication","pdf":"https://arxiv.org/pdf/2610.05870.pdf","url":"https://arxiv.org/abs/2610.05870","submittedDate":"2026-10-05","upvotes":10,"tags":["Agent Safety"],"announceDate":"2026-10-06","abstract":"Generative models can synthesize high-quality inauthentic multimedia content that is already being misused at scale. We evaluate twenty deepfake detectors against ten generators released in the last four years and find accuracy decreasing over time, from near-perfect 99.5% to 76%. Adversarial perturbations further reduce every baseline detector to below 2% accuracy, effectively inverting the detector's assigned label. We argue that this unreliability reflects a fundamental ambiguity: generators can reproduce authentic content exactly (e.g., through memorization), so content alone cannot reveal the true provenance label.For this reason, content produced by a generator must admit a faithful reconstruction by that same generator, and finding such a reconstruction makes synthetic provenance plausible and authenticity plausibly deniable.We therefore propose and evaluate a detection paradigm t"},{"arxiv":"https://arxiv.org/abs/2610.05719","topics":["Evaluation","Fine-tuning"],"authors":["Seonghoon Yu","Dongwon Kim","HyungRok Jung","Yoonjae Baek","Byung-kwan Lee","Suha Kwak","Jeany Son"],"hfUrl":"https://huggingface.co/papers/2610.05719","id":"arxiv:2610.05719","date":"2026-10-06","source":"hf","title":"When to Switch: Reliable Action-Chunk Extension for Vision-Language-Action Models","pdf":"https://arxiv.org/pdf/2610.05719.pdf","url":"https://arxiv.org/abs/2610.05719","upvotes":9,"tags":["Evaluation","Fine-tuning"],"abstract":"Vision-Language-Action (VLA) models serve as unified policies for robotic manipulation, yet their expensive inference forces robots to pause between policy calls, resulting in stop-and-go execution that interrupts smooth motion and prolongs task completion. Extending the action chunk reduces policy calls and hence these pauses, but predicting farther into the future makes long-chunk execution unreliable. To understand where this unreliability arises, we analyze action errors within long chunks and find that they concentrate around transitions between manipulation subskills, growing sharply with chunk length. This suggests the importance of transition timing, i.e., when to switch subskills within a chunk. Motivated by this observation, we introduce RACE (Reliable Action-Chunk Extension), a framework that predicts the transition timing from an auxiliary one-step denoising pass and conditio"},{"arxiv":"https://arxiv.org/abs/2610.06851","topics":["Agent Safety","LLM Training","Reasoning","RL for LLM"],"authors":["Sophie L. Wang","Amil Dravid","Rulin Shao","Kevin Farhat","Sewon Min","Alexei A. Efros"],"hfUrl":"https://huggingface.co/papers/2610.06851","id":"arxiv:2610.06851","date":"2026-10-06","source":"hf","title":"Base Models Can Reason By Taking a Cue From Training Data","pdf":"https://arxiv.org/pdf/2610.06851.pdf","url":"https://arxiv.org/abs/2610.06851","submittedDate":"2026-10-05","upvotes":8,"tags":["Agent Safety","LLM Training","Reasoning","RL for LLM"],"announceDate":"2026-10-06","abstract":"In this paper, we study how training data creates associations between the tokens at the start of a base model's response and the reasoning behavior that follows. First, we demonstrate that fixing particular starting token cues makes a base model's performance competitive with that of its reinforcement learning (RL)-trained counterparts on math and coding. For instance, the cue \".\\n\\nOkay\" raises Olmo-3-7B's MATH-500 pass@1 accuracy from 42% to 78%, while \"Alright,\" raises Qwen3-14B's from 72% to 87%. Second, RL makes these cues more likely, while fixing them recovers much of its performance gain over the base model. Third, we trace the reasoning effects of token cues to the training data. We perform causal data interventions to turn an arbitrary word, such as \"chicken\", into an effective reasoning cue, or remove an existing cue's effect. A similar edit makes the prompt instruction \"Thin"},{"arxiv":"https://arxiv.org/abs/2610.04318","topics":["VLM Training","Evaluation"],"authors":["Sixun Dong","Wei Li","Andong Deng","Qi Qian","Victor Zhu","Zhengping Ji","Chen Chen"],"hfUrl":"https://huggingface.co/papers/2610.04318","id":"arxiv:2610.04318","date":"2026-10-06","source":"hf","title":"Rethinking Long-Video Efficiency: A Joint Allocation Perspective on Frames, Pixels, and Front-End Latency","pdf":"https://arxiv.org/pdf/2610.04318.pdf","url":"https://arxiv.org/abs/2610.04318","submittedDate":"2026-10-03","upvotes":8,"tags":["VLM Training","Evaluation"],"announceDate":"2026-10-06","abstract":"Efficient long-video understanding with vision-language models (VLMs) is often framed as selecting informative frames or visual tokens at a fixed native resolution. We show that per-frame resolution can instead be traded for denser temporal coverage, while front-end decoding latency depends on the size of the candidate pool rather than the final token budget. An empirical study across multiple VLMs and long-video benchmarks yields three findings: dense low-resolution sampling outperforms sparse native-resolution sampling at matched token budgets; resolution-sensitive tasks benefit from selected high-resolution frames; and front-end decoding dominates wall time for hour-long videos. Motivated by these findings, we introduce LoHi, a training-free, single-pass framework that combines a dense low-resolution video stream with sparse high-resolution image frames through the VLM's native video "},{"arxiv":"https://arxiv.org/abs/2610.04616","topics":["VLM Training"],"authors":["Mingyu Liu","Chonghao Sima","Tianjian Feng","Hanqing Wang","Cong Chen","Hao Chen","Chunhua Shen"],"hfUrl":"https://huggingface.co/papers/2610.04616","id":"arxiv:2610.04616","date":"2026-10-06","source":"hf","title":"PerturBot: Breaking Shortcut Priors in Vision-Language-Action Models with Perturbative Training","pdf":"https://arxiv.org/pdf/2610.04616.pdf","url":"https://arxiv.org/abs/2610.04616","submittedDate":"2026-10-03","upvotes":7,"tags":["VLM Training"],"announceDate":"2026-10-06","abstract":"A vision--language--action (VLA) policy can complete complex tasks while ignoring the evidence that should determine its actions. An object held near the wrist camera can displace the instructed target. Language and action show the same pattern: a familiar noun can trigger the operation it was paired with in training even after the verb changes, and a gripper that closed on nothing may lift anyway. We call these dependencies modality shortcuts: regularities in successful demonstrations make visual, lexical, or motor cues sufficient to predict expert actions without the task evidence needed for the underlying decision. More demonstrations of the same kind can raise task success while leaving these shortcuts intact. We propose Perturbot which makes task-relevant evidence easier to use and shortcuts insufficient on their own: it applies task-preserving wrist-view perturbations, enriches ins"},{"arxiv":"https://arxiv.org/abs/2610.04137","topics":["Multi-Agent","Evaluation"],"authors":["Som Sagar","Shasha Li","Hejie Cui","Ransalu Senanayake","Sercan Ö. Arık"],"hfUrl":"https://huggingface.co/papers/2610.04137","id":"arxiv:2610.04137","date":"2026-10-06","source":"hf","title":"Dynamic Harness Search: Building Multi-Agent Systems Per-Query via Prediction","pdf":"https://arxiv.org/pdf/2610.04137.pdf","url":"https://arxiv.org/abs/2610.04137","submittedDate":"2026-10-02","upvotes":6,"tags":["Multi-Agent","Evaluation"],"announceDate":"2026-10-06","abstract":"Agent harnesses specify the roles, instructions, tools, and communication structure used to solve a task, and the right harness depends on the query. Because the value of each design choice is observable only through execution, tailoring a harness to each query has required either executing alternatives at inference time or costly manual design. We introduce SHIFT, which moves execution out of the per-query search loop. A local LLM architect learns a policy over harness-building actions from search, and a value function that predicts, from measured executions, a utility balancing accuracy against execution cost. For each query, Monte Carlo tree search uses these predictions to construct a harness. Across 9,193 tasks in six benchmarks, from math to document and general-assistant tasks, with a Gemini 3.5 Flash executor, SHIFT attains the highest mean accuracy, about 80%, outperforming 17 b"},{"arxiv":"https://arxiv.org/abs/2610.03872","topics":["Reflection"],"authors":["Peter Chen","Wotao Yin"],"hfUrl":"https://huggingface.co/papers/2610.03872","id":"arxiv:2610.03872","date":"2026-10-06","source":"hf","title":"Training Numerical Intelligence via Auto-Diagnosis and Skill Discovery","pdf":"https://arxiv.org/pdf/2610.03872.pdf","url":"https://arxiv.org/abs/2610.03872","submittedDate":"2026-10-02","upvotes":4,"tags":["Reflection"],"announceDate":"2026-10-06","abstract":"AI agents are becoming increasingly capable of generating scientific code, but generating code is not the same as improving the algorithms behind it. For numerical solvers, execution feedback can expose poor performance, but rarely reveals its underlying cause and how to address it. We introduce Auto-Diagnosis and Skill Discovery (ADSD), a framework that links numerical diagnosis to reusable solver self-improvement. ADSD follows a diagnosis-first paradigm that first explains why a solver performs poorly, then uses this diagnosis to guide the discovery of appropriate numerical methods. The resulting knowledge is packaged into reusable solver skills, turning solver improvement from trial-and-error editing into a structured process of diagnosis, discovery, and implementation. Across four challenging numerical domains--power flow equation, AC optimal power flow control, stiff ordinary differ"},{"arxiv":"https://arxiv.org/abs/2610.05033","topics":["Reasoning","Planning","Code Agent","Evaluation"],"authors":["Wei Wu","Ziyang Xu","Zeyu Zhang","Yang Zhao","Hao Tang"],"hfUrl":"https://huggingface.co/papers/2610.05033","id":"arxiv:2610.05033","date":"2026-10-06","source":"hf","title":"Code2Games: Enabling Coding Agents for Gaming World Generation","pdf":"https://arxiv.org/pdf/2610.05033.pdf","url":"https://arxiv.org/abs/2610.05033","submittedDate":"2026-10-04","upvotes":3,"tags":["Reasoning","Planning","Code Agent","Evaluation"],"announceDate":"2026-10-06","abstract":"Generating a high-quality gaming world from a natural-language game intent requires joint reasoning about scene structure, spatial layout, gameplay objectives, interactive entities, and executable gameplay logic. Existing coding agents can generate individual assets, scenes, or scripts, but often struggle to maintain consistency across these components. We propose Code2Games, an agentic framework that builds a structured gaming world upon a base Blender world generated from the same game intent. Code2Games coordinates scene analysis, gameplay planning, constrained gaming-world generation, and gaming-engine customization through a shared scene-gameplay representation with persistent element correspondence. After world generation, Code2Games adapts the generated world to Unreal Engine 5 and employs an execution-guided reconstruction process that uses compilation diagnostics, runtime feedba"},{"arxiv":"https://arxiv.org/abs/2605.21318","topics":["Reasoning","Evaluation"],"authors":["Lucheng Fu","Ye Yu","Yiyang Wang","Yiqiao Jin","Haibo Jin","B. Aditya Prakash","Haohan Wang"],"hfUrl":"https://huggingface.co/papers/2605.21318","id":"arxiv:2605.21318","date":"2026-10-06","source":"hf","title":"TextReg: Mitigating Prompt Distributional Overfitting via Regularized Text-Space Optimization","pdf":"https://arxiv.org/pdf/2605.21318.pdf","url":"https://arxiv.org/abs/2605.21318","upvotes":3,"tags":["Reasoning","Evaluation"],"abstract":"Large language models (LLMs) are highly sensitive to the prompts used to specify task objectives and behavioral constraints. Many recent prompt optimization methods iteratively rewrite prompts using LLM-generated feedback, but the resulting prompts often become longer, accumulate narrow sample-specific rules, and generalize poorly beyond the training distribution. We study this failure mode as prompt distributional overfitting and argue that it reflects a lack of representation control in discrete text-space optimization. We formalize this view through representational inefficiency, a dual-factor measure that decomposes prompt inefficiency into capacity cost and scope narrowness, attributing distributional prompt overfitting to their coupled growth during optimization. We propose TextReg, a regularization framework that realizes a soft-penalty objective through regularized textual gradie"},{"arxiv":"https://arxiv.org/abs/2610.06184","topics":["VLM Training","Evaluation","Fine-tuning"],"authors":["Zaibin Zhang","Binghao Ran","Yuhan Wu","Zhongbo Zhang","Yifan Wang","Junwei Jiang","Junlan Xiao","Wangcheng Shi","Li Kang","Yiran Qin","Zhenfei Yin","Lijun Wang","Huchuan Lu"],"hfUrl":"https://huggingface.co/papers/2610.06184","id":"arxiv:2610.06184","date":"2026-10-06","source":"hf","title":"Arm-wise Compositional Generalization in Dual-Arm Vision-Language-Action Models","pdf":"https://arxiv.org/pdf/2610.06184.pdf","url":"https://arxiv.org/abs/2610.06184","upvotes":1,"tags":["VLM Training","Evaluation","Fine-tuning"],"abstract":"Generalization in multi-arm collaboration can be studied as composing familiar atomic skills in new ways across arms. However, existing evaluations offer limited insight into which training and architectural choices support this ability under different coordination requirements. We introduce ACG-Bench, a benchmark for Arm-wise Compositional Generalization that provides a common testbed for studying skill recomposition in dual-arm policies. It contains 23 task--condition pairs across 8 task families, with 6 in-domain conditions and 17 unseen compositions covering reordering, synchronization, their combination, and cross-task composition. All methods receive the same per-arm atomic prompts, and success requires achieving the task goal while satisfying physical milestones and specified order or timing constraints. Using π_{0.5} as a common vision-language-action backbone, we compare represe"},{"arxiv":"https://arxiv.org/abs/2610.04292","topics":["Reasoning","Evaluation","Alignment"],"authors":["Jiateng Liu","Rushi Wang","Cheng Qian","Xuejun Zhang","Sun Li","Jiayu Liu","Yifan Shen","Xu Cao","Jiarui Yao","Bingxuan Li","Ruhi Sarikaya","Heng Ji"],"hfUrl":"https://huggingface.co/papers/2610.04292","id":"arxiv:2610.04292","date":"2026-10-06","source":"arxiv","title":"LMBuild: Evaluating LLM Agents for Generating Buildable and Functional Structures","pdf":"https://arxiv.org/pdf/2610.04292.pdf","url":"https://arxiv.org/abs/2610.04292","submittedDate":"2026-10-03","upvotes":23,"tags":["Reasoning","Evaluation","Alignment"],"announceDate":"2026-10-06","abstract":"LLM-based agents are increasingly capable of generating complex 3D structures, with the potential to reshape how objects are designed and realized in the physical world. Yet, producing elegant geometry is fundamentally different from producing objects that can be built and perform their intended functions. Existing evaluations largely focus on geometric quality while overlooking physical realizability. We introduce LMBuild, a benchmark for evaluating LLM agents on generating buildable and functional structures. LMBuild represents generated objects as assembled structures comprising part decompositions, joints, materials, and sequences. To support reproducible evaluation, we provide a unified framework consisting of: (1) an interactive environment in which agents can use tools to retrieve, create, and place components to construct objects; (2) a curated benchmark that repurposes establish"},{"arxiv":"https://arxiv.org/abs/2610.06648","topics":["Post-Training","Evaluation"],"authors":["Ilya Drobyshevskiy","Ilia Sudakov","Maksim Semenov","Denis Kuznedelev","Maksim Ignatov","Pavel Temirchev","Nikita Balagansky","Viacheslav Meshchaninov","Nikita Gushchin","Dmitry Baranchuk"],"hfUrl":"https://huggingface.co/papers/2610.06648","id":"arxiv:2610.06648","date":"2026-10-06","source":"arxiv","title":"Representation-Space MMD for Diffusion Language Models","pdf":"https://arxiv.org/pdf/2610.06648.pdf","url":"https://arxiv.org/abs/2610.06648","submittedDate":"2026-10-05","upvotes":15,"tags":["Post-Training","Evaluation"],"announceDate":"2026-10-06","abstract":"We introduce a post-training method for diffusion language models (DLMs) that minimizes Maximum Mean Discrepancy (MMD) between generated and reference distributions in the feature space of a frozen pretrained DLM. To estimate MMD, we retain contextual features at individual token positions, obtaining multiple observations per sequence from a single extractor pass. We optimize this objective using policy gradients for discrete models and direct differentiation through generated latents for continuous models. In both cases, computing the loss directly from these features enables efficient post-training without full sampling trajectories or jointly trained auxiliary models. Experiments show lower generative perplexity at comparable entropy on OpenWebText and better accuracy-computation trade-offs on GSM8K. On 16B DMax-LLaDA2.0 models with hybrid masked-uniform diffusion, we increase decodin"},{"arxiv":"https://arxiv.org/abs/2610.05107","topics":["Agentic Search","Reasoning","Planning","Evaluation"],"authors":["Congfeng Cao","Lipeng Zuo","Konstantinos Papakostas","Qiwei Xu","Songwei Xu","Lun Zhou","Zhaochun Ren","Yougang Lyu","Xiaohui Yan"],"hfUrl":"https://huggingface.co/papers/2610.05107","id":"arxiv:2610.05107","date":"2026-10-06","source":"arxiv","title":"SearchJev: A Fast and Calibrated System-1 Model for Search Agents","pdf":"https://arxiv.org/pdf/2610.05107.pdf","url":"https://arxiv.org/abs/2610.05107","submittedDate":"2026-10-04","upvotes":13,"tags":["Agentic Search","Reasoning","Planning","Evaluation"],"announceDate":"2026-10-06","abstract":"Search agents repeatedly make short decisions about relevance, evidence sufficiency, and search actions. Using generative language models for these decisions introduces latency and unreliable confidence. We present SearchJev, a fast and calibrated System-1 model that separates search decisions from System-2 reasoning and generation. Given a search state and a decision schema, SearchJev directly scores legal options without autoregressive output generation. We propose Soft-Label Learning for Calibrated Decisions (SLCD) to learn decision probabilities from uncertain supervision and calibrate their confidence. In a dual-system search agent, SearchJev handles short decisions and delegates uncertain judgments to System 2, which retains planning, query generation, and answer composition. We also introduce SearchDecision-Bench, a benchmark unifying six types of search decisions for training and"},{"arxiv":"https://arxiv.org/abs/2610.05622","topics":["Planning","Evaluation"],"authors":["Dolly Sah","Tanmay Sah","Harshul Jain","Tanya Sah"],"hfUrl":"https://huggingface.co/papers/2610.05622","id":"arxiv:2610.05622","date":"2026-10-06","source":"arxiv","title":"UndoBench: Separating Task Competence from Recovery Capability in Tool-Using AI Agents","pdf":"https://arxiv.org/pdf/2610.05622.pdf","url":"https://arxiv.org/abs/2610.05622","submittedDate":"2026-10-04","upvotes":7,"tags":["Planning","Evaluation"],"announceDate":"2026-10-06","abstract":"Tool-using AI agents are increasingly deployed across enterprise software systems, yet widely used benchmarks primarily evaluate nominal task completion, conflating baseline planning competence with operational fault recovery. We introduce UndoBench, a benchmark spanning 36 base workflows and 36 fault scenarios across 8 enterprise domains, decoupling task competence from recovery capability via counterfactual paired trials under identical seeds alongside wire-level effect-history and environment-state oracles. On 12 held-out TEST workflows across two open-weight models, two frameworks, and three recovery paradigms (5,760 executions / 2,880 paired trials) in the frozen lost-acknowledgment study, nominal competence reached 83.54% while conditional recovery success rate (CRSR) fell to 46.72%, with naive retry producing duplicate external effects in 53.33% of trials. Extensions to commercial"},{"arxiv":"https://arxiv.org/abs/2610.06666","topics":["Reasoning","Evaluation"],"authors":["Yassine Ouali","Adrian Bulat","Georgios Tzimiropoulos"],"hfUrl":"https://huggingface.co/papers/2610.06666","id":"arxiv:2610.06666","date":"2026-10-06","source":"arxiv","title":"What Matters for Latent Reasoning with Flow Matching","pdf":"https://arxiv.org/pdf/2610.06666.pdf","url":"https://arxiv.org/abs/2610.06666","submittedDate":"2026-10-05","upvotes":6,"tags":["Reasoning","Evaluation"],"announceDate":"2026-10-06","abstract":"Latent reasoning lets a large language model (LLM) think in a continuous space and verbalize only the answer. We argue that an effective latent thought must meet five requirements: it should be useful, helping produce the correct answer rather than merely changing it, diverse, so that resampling yields different reasoning trajectories, explainable, so that a decoded chain of thought (CoT) reflects reasoning the answer actually follows, refinable with more inference compute, and efficient, costing less than an explicit CoT at comparable accuracy. Current methods rarely meet these requirements: they learn shortcuts from the question, distill the explicit CoT into their weights, or imitate it one token at a time. We focus on flow matching in a learned latent space, the family we argue is best placed to meet them, and identify the training choices that make it work. The result is Flow-based "},{"arxiv":"https://arxiv.org/abs/2610.05750","topics":["Agentic RAG","Reasoning","Evaluation"],"authors":["Reza Esfandiarpoor","Radek Osmulski","Yauhen Babakhin","Gabriel de Souza P. Moreira","Oliver Holworthy","Jie He","Ronay Ak","Jiarui Cai","Ryan Chesler","Bo Liu","Even Oldridge"],"hfUrl":"https://huggingface.co/papers/2610.05750","id":"arxiv:2610.05750","date":"2026-10-06","source":"arxiv","title":"Beyond Semantic Similarity: Performance and Costs of Agentic Retrieval for Complex Tasks","pdf":"https://arxiv.org/pdf/2610.05750.pdf","url":"https://arxiv.org/abs/2610.05750","submittedDate":"2026-10-05","upvotes":3,"tags":["Agentic RAG","Reasoning","Evaluation"],"announceDate":"2026-10-06","abstract":"Modern information systems, including many agentic workflows, use dense retrieval to explore large amounts of unstructured data. However, dense retrieval relies on surface-level semantic similarity, which is insufficient for increasingly complex search applications. Here, we investigate agentic retrieval that combines the reasoning capabilities of Large Language Models (LLMs) with the efficient corpus exploration of retrievers in a ReAct agentic loop to solve complex retrieval tasks. In our experiments, we show that agentic retrieval is more effective than standard retrieval, improving nDCG@10 by 8.7 points using the same embedding model. Moreover, while specialized retrieval methods struggle on out-of-domain tasks, agentic retrieval is highly generalizable: the same pipeline achieves competitive results on both the ViDoRe v3 and BRIGHT leaderboards. However, this improvement comes at a "},{"arxiv":"https://arxiv.org/abs/2610.04777","topics":["LLM Training","VLM Training","Reasoning","Planning","Hallucination","Evaluation","Interpretability"],"authors":["Pronoma Banerjee","Anuva Shah","Jason Wu","Md. Masudur Rahman","Sanjay Mohanty","Satya Kurada","Juan P. Wachs"],"id":"arxiv:2610.04777","date":"2026-10-06","source":"arxiv","title":"ARISE: Adaptive Agentic Reasoning with Image-grounded Self-Evaluation for Interpretable IBD Assessment","pdf":"https://arxiv.org/pdf/2610.04777.pdf","url":"https://arxiv.org/abs/2610.04777","submittedDate":"2026-10-03","upvotes":0,"tags":["LLM Training","VLM Training","Reasoning","Planning","Hallucination"],"announceDate":"2026-10-06","abstract":"Inflammatory bowel disease (IBD) requires frequent imaging-based assessment, yet interpretation of modalities such as wireless capsule endoscopy (WCE) and intestinal ultrasound remains heavily dependent on specialist expertise. Vision-Language Models (VLMs) demonstrate significant potential in multimodal medical image analysis, but their clinical adoption is hindered by their insufficient domain-specific reasoning, susceptibility to hallucination, scarcity of high quality training data in fine-grained diagnostics and limited interpretability. We introduce ARISE (Adaptive Agentic Reasoning with Image-grounded Self-Evaluation), an autonomous planning framework that models few-shot medical image understanding as a sequential agentic workflow. ARISE structures agent execution into a transparent 5-stage workflow: hypothesis generation, image-grounded evidence summarization, evidence-condition"},{"arxiv":"https://arxiv.org/abs/2610.04269","topics":["Agent Safety","Post-Training","Reasoning","Evaluation","Alignment","Fine-tuning","Reflection"],"authors":["Zixuan Wang","Hao Li","Fengyu Gao","G. Edward Suh","Yi Zeng","Yevgeniy Vorobeychik","Ning Zhang","Chaowei Xiao"],"id":"arxiv:2610.04269","date":"2026-10-06","source":"arxiv","title":"Self-Reflection Fine-Tuning: Enhancing Agent Security against Prompt Injection Attacks from Failure Experience","pdf":"https://arxiv.org/pdf/2610.04269.pdf","url":"https://arxiv.org/abs/2610.04269","submittedDate":"2026-10-03","upvotes":0,"tags":["Agent Safety","Post-Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-10-06","abstract":"Large language model (LLM) agents are increasingly deployed in tool-augmented environments, but their reliance on external inputs makes them highly vulnerable to prompt injection attacks that can hijack task objectives. Existing safety alignment methods rely on static expert trajectories or preference optimization, limiting their ability to generalize to adaptive attack patterns. In this work, we propose Self-Reflection Fine-Tuning (SRFT), a training framework that enables agents to improve robustness by learning from their own failure experiences under adversarial conditions. Instead of passively imitating expert behaviors, SRFT exposes the agent to compromised trajectories constructed via injected attacks, and leverages an expert model to generate structured self-reflection reasoning that contrasts unsafe and optimal actions. This reflective supervision teaches the agent to identify ma"},{"arxiv":"https://arxiv.org/abs/2610.04469","topics":["LLM Training","VLM Training","Reasoning","Evaluation","Reflection","Multimodal Agent"],"authors":["Youngwan Lee","Yong-Ju Lee","Sung Ju Hwang"],"id":"arxiv:2610.04469","date":"2026-10-06","source":"arxiv","title":"Trinity: Self-Evolving Vision-Language Models with a Self-Verifier","pdf":"https://arxiv.org/pdf/2610.04469.pdf","url":"https://arxiv.org/abs/2610.04469","submittedDate":"2026-10-03","upvotes":0,"tags":["LLM Training","VLM Training","Reasoning","Evaluation","Reflection"],"announceDate":"2026-10-06","abstract":"Self-evolving vision-language models (VLMs), a form of self-improvement in which a model generates its own training data from unlabeled images, are a promising route toward agents that expand their reasoning capability in an unsupervised manner, without relying on ever-larger annotation budgets. Existing methods pair a Questioner that proposes problems with a Solver that answers them, but reward both roles mainly by agreement among sampled answers. Agreement is a weak proxy for truth: it cannot tell whether a question is grounded in the image, whether the proposed reference answer is right, or whether a confident majority is wrong in the same way. We present Trinity, in which one VLM plays three roles, Questioner, Solver, and Verifier, and the Verifier is a self-verifier: an exponential moving average (EMA) of the policy itself, requiring neither labels nor an external judge. The Verifie"},{"arxiv":"https://arxiv.org/abs/2610.05367","topics":["LLM Training","Reasoning","Code Agent","Evaluation","Fine-tuning","RL for LLM"],"authors":["Prithwish Jana","Viet Bach Hoang","Logan Luna","Viresh Pati","Akash Singirikonda","Cy Xie","Lisa Carbone","Wuyang Chen","Walter Moreira","Joe Stubbs","Sriram Vishwanath","Vijay Ganesh"],"id":"arxiv:2610.05367","date":"2026-10-06","source":"arxiv","title":"AIProver: Agentic Auto-Formalization of Mathematical Research via Certificate-Driven Evolving Harness","pdf":"https://arxiv.org/pdf/2610.05367.pdf","url":"https://arxiv.org/abs/2610.05367","submittedDate":"2026-10-04","upvotes":0,"tags":["LLM Training","Reasoning","Code Agent","Evaluation","Fine-tuning"],"announceDate":"2026-10-06","abstract":"Proof auto-formalization translates natural-language (NL) theorems and proofs into a formal language (FL) such as Lean, enabling mechanical verification. Despite rapid progress, research-level proofs often depend on concepts missing from leading proof assistant libraries (e.g., Lean's Mathlib), and successful compilation does not guarantee that a translation preserves the theorem's meaning or the proof's reasoning. Furthermore, aligned NL-FL training data are scarce, and leading agents often rely on costly frontier models and manually engineered harnesses. To address the above issues, we present AIProver, an agentic framework for autonomous proof auto-formalization and proof synthesis (AFPS) that jointly post-trains a 119B open-weight language model and evolves its agentic, tool-calling harness with HarnessEvolve. Verifiers assess type correctness, proof completeness, and semantic correc"},{"arxiv":"https://arxiv.org/abs/2610.05861","topics":["VLM Training","Computer Use","Evaluation","Fine-tuning","Data Engine","World Model"],"authors":["Yongxin Ning","Runliang Niu","Qianli Xing","Zhiyi Duan","Qingzu He","Pan Wang","Qi Wang"],"id":"arxiv:2610.05861","date":"2026-10-06","source":"arxiv","title":"Imagine to Act: High-Fidelity Data Synthesis via Image Editing World Model for Scalable GUI Agent Training","pdf":"https://arxiv.org/pdf/2610.05861.pdf","url":"https://arxiv.org/abs/2610.05861","submittedDate":"2026-10-05","upvotes":0,"tags":["VLM Training","Computer Use","Evaluation","Fine-tuning","Data Engine"],"announceDate":"2026-10-06","abstract":"Graphical User Interface (GUI) agents have emerged as a promising paradigm for automating complex digital workflows across diverse applications. However, training highly capable and generalizable agents fundamentally relies on massive, high-fidelity visual-action trajectories, which are notoriously difficult to acquire. While human demonstrations are unscalable, existing GUI world models rely on text descriptions or HTML rendering, discarding crucial pixel-level visual details like icons and layout styles. To address this issue, we introduce Infinite-Dreamer, a simulation-free data synthesis method powered by a pixel-level Image Editing World Model. By conceptualizing GUI transitions as image editing tasks, we leverage Vision-Language Models (VLMs) to describe action-induced UI changes as structured delta-text. We then fine-tune an image editing backbone to controllably synthesize realis"},{"arxiv":"https://arxiv.org/abs/2610.05481","topics":["LLM Training","Multi-Agent","Code Agent","Evaluation","Fine-tuning"],"authors":["Zhizhou Gu","Xianting Wu","Siyu Gu","Tian Zhang","Kejian Tong"],"id":"arxiv:2610.05481","date":"2026-10-06","source":"arxiv","title":"CodeForge-MA: Execution-Verified Multi-Agent Learning with Language-Conditioned LoRA for Multilingual Code Generation","pdf":"https://arxiv.org/pdf/2610.05481.pdf","url":"https://arxiv.org/abs/2610.05481","submittedDate":"2026-10-04","upvotes":0,"tags":["LLM Training","Multi-Agent","Code Agent","Evaluation","Fine-tuning"],"announceDate":"2026-10-06","abstract":"Large language models for code generation often fail on execution, multilingual coverage, and contamination control, especially under frozen backbone constraints. We present CodeForge-MA, a unified framework that improves code synthesis through a multi-agent data forge, execution verified reinforced instruction tuning, and a language conditioned mixture of LoRA adapters. Four specialized agents, Composer, Reviewer, Executor, and Curator, iteratively refine instruction code pairs, validate them with tests, and filter duplicates and benchmark leakage. During training, we combine masked supervised fine tuning with a test driven reinforcement objective to align generations with executable correctness. For the larger model, we use sparse expert routing over low rank adapters to improve cross language transfer while keeping the base model unchanged at inference. Experiments show that joint dat"},{"arxiv":"https://arxiv.org/abs/2610.05782","topics":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation","Agent Framework"],"authors":["Shovan Roy","Lopamudra Praharaj","Maanak Gupta","Bhavani Thuraisingham"],"id":"arxiv:2610.05782","date":"2026-10-06","source":"arxiv","title":"Agentic-ZTA: A Multi-Agent Architecture for Autonomous Zero Trust Enforcement","pdf":"https://arxiv.org/pdf/2610.05782.pdf","url":"https://arxiv.org/abs/2610.05782","submittedDate":"2026-10-05","upvotes":0,"tags":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation","Agent Framework"],"announceDate":"2026-10-06","abstract":"Agentic AI is emerging as a promising paradigm for automating complex cybersecurity decisions, yet its use in enforcing zero trust introduces significant challenges in safety, reliability, and policy compliance. This paper presents Agentic AI based zero trust architecture (Agentic-ZTA) that operationalizes the NIST SP 800-207 ZTA architecture control loop through coordinated multi- agent decision pipeline. In the proposed framework, policy knowledge is embedded into a retrieval-augmented generation pipeline and retrieved at inference time as top-k relevant policies. Access requests are intercepted by the Policy Enforcement Point (PEP), enriched with contextual metadata. The request context is routed to a policy engine agent which invokes domain-specialized core agents first followed by supporting agents, if further evaluation needed. AI agents reason over access context, policy constrain"},{"arxiv":"https://arxiv.org/abs/2610.06347","topics":["Error Attribution","Post-Training","LLM Training","Evaluation","Reflection"],"authors":["Xingbo Yao","Xiaoman Wang","Zhengwu Lei","Tinghui Luo","YiLin Zhang","Yuefeng Wu","Yijie Xu","Tianfu Wang","Qingyuan Zhan","Ye Guo","Daoxin Zhang","Zhe Xu","Jian Liu","Hui Xiong"],"id":"arxiv:2610.06347","date":"2026-10-06","source":"arxiv","title":"ImproveAnyTask: An Autonomous Post-Training Harness for Iterative Model Self-Improvement","pdf":"https://arxiv.org/pdf/2610.06347.pdf","url":"https://arxiv.org/abs/2610.06347","submittedDate":"2026-10-05","upvotes":0,"tags":["Error Attribution","Post-Training","LLM Training","Evaluation","Reflection"],"announceDate":"2026-10-06","abstract":"Adapting general-purpose large language models to specific tasks requires substantial human effort in designing data and training strategies. Sustaining improvement is especially challenging because model updates change the error distribution, requiring strategies to be continually refined. We introduce ImproveAnyTask, an autonomous post-training harness that improves task performance under a limited compute budget. Drawing inspiration from gradient-based parameter optimization, the harness organizes adaptation into error attribution, update-direction selection, and executable model updates. It combines metric-level and case-level analysis to identify a focal problem, then investigates research-backed strategies and compares their reported gains and reproduction difficulty. The selected strategy is translated into training data and a training configuration, with small-scale execution che"},{"arxiv":"https://arxiv.org/abs/2610.04387","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Wenxin Zhan","Yizheng Jiao","Haifeng Song","Shuai Xu","Chencheng Pan","Jiayi Feng","Anjie Xie"],"id":"arxiv:2610.04387","date":"2026-10-06","source":"arxiv","title":"TrustMed-RL: Long-Horizon Reinforcement Learning for Evidence-Grounded Clinical Diagnosis","pdf":"https://arxiv.org/pdf/2610.04387.pdf","url":"https://arxiv.org/abs/2610.04387","submittedDate":"2026-10-03","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-06","abstract":"Medical language models can produce correct diagnoses despite incomplete investigations and unsupported reasoning. To support long-horizon, evidence-grounded diagnosis, we introduce \\textbf{TrustMed-RL}. Built from PubMed rare-disease cases and over 24,000 manually annotated image panels, it integrates interviews, examinations, testing, specialist consultation, and literature search through state-dependent actions. Our 8B vision--language policy, trained with clinically adapted GiGPO and coverage-adjusted diagnostic rewards, achieves 37.1\\% diagnostic accuracy on 2,500 evaluation cases, outperforming all evaluated open-weight baselines and improving over supervised fine-tuning by 12.4 percentage points.. When success additionally requires acquiring at least 50\\% of supporting test evidence, TrustMed-RL achieves 32.5\\%, exceeding GPT-4o by 6.8 percentage points. Furthermore, it surpasses "},{"arxiv":"https://arxiv.org/abs/2610.05176","topics":["Multi-Agent","Reasoning","Memory","Evaluation","Agent Framework"],"authors":["Ao Tian","Jialong Liu","Daqi Zheng","Xin Sun","Mengting Li","Zhizhao Xiao","Zijian Huang","Honglei Wang","Zijian Hei","Yukun Yan"],"id":"arxiv:2610.05176","date":"2026-10-06","source":"arxiv","title":"AECG: Asymmetric Experience Consolidation and Governance In Multi-Agent Systems","pdf":"https://arxiv.org/pdf/2610.05176.pdf","url":"https://arxiv.org/abs/2610.05176","submittedDate":"2026-10-04","upvotes":0,"tags":["Multi-Agent","Reasoning","Memory","Evaluation","Agent Framework"],"announceDate":"2026-10-06","abstract":"Large language model (LLM)-based multi-agent systems increasingly rely on memory to transform execution trajectories into reusable procedural knowledge. Yet repeated retrieval also makes memory errors persistent: memory pollution arises when outdated, weakly supported, or spuriously successful procedures become recurring components of future reasoning. Multi-agent execution introduces an additional structural risk. Scope collapse occurs when procedural knowledge escapes the coordination scope in which it was shown effective and is repeatedly reused at incompatible decision levels, allowing local errors to influence cascades of downstream decisions. Meanwhile, task-level failures provide ambiguous supervision because they rarely reveal which recalled knowledge was responsible. We introduce AECG, a framework for asymmetric experience consolidation and governance for multi-agent systems. AE"},{"arxiv":"https://arxiv.org/abs/2610.06413","topics":["LLM Training","VLM Training","Reasoning","Hallucination","Evaluation"],"authors":["Rafael Teixeira Sousa","Vinícius Paulo Lopes de Oliveira","Elisa Ayumi Masasi de Oliveira","Luiza Martins de Freitas Cintra","Fernanda Bufon Färber","Igor Dias Aguiar","Julia Yasmim de Almeida Nobre","Arlindo Rodrigues Galvão Filho"],"id":"arxiv:2610.06413","date":"2026-10-06","source":"arxiv","title":"SpatialChain: A Benchmark for Auditing Spatial Reasoning Faithfulness in VLMs","pdf":"https://arxiv.org/pdf/2610.06413.pdf","url":"https://arxiv.org/abs/2610.06413","submittedDate":"2026-10-05","upvotes":0,"tags":["LLM Training","VLM Training","Reasoning","Hallucination","Evaluation"],"announceDate":"2026-10-06","abstract":"Thinking-enabled vision-language models (VLMs) report ever-higher accuracy on spatial benchmarks, yet final-answer scores cannot reveal whether a correct prediction reflects faithful spatial reasoning or a linguistic shortcut. We introduce SpatialChain, a dataset of 28,350 training and 899 test examples pairing spatially-oriented GQA questions with scene-graph-grounded reasoning chains, retained only when the generated answer matches the symbolic ground truth, and a two-axis evaluation combining objective chain-overlap metrics with a scene-graph-aware LLM judge that scores faithfulness and completeness independently of the final answer. Applied to nine thinking-enabled VLMs, the protocol surfaces three findings invisible to standard accuracy: (i) four of nine models achieve $\\geq$79% VQA accuracy while exhibiting shortcut rates above 39%, i.e., correct answers whose reasoning the judge m"},{"arxiv":"https://arxiv.org/abs/2610.06031","topics":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"authors":["Tamara Czinczoll","Julie Kallini","Gerard de Melo","Chen Shani"],"id":"arxiv:2610.06031","date":"2026-10-06","source":"arxiv","title":"LightMTP: Lightweight Latent Multi-Token Prediction","pdf":"https://arxiv.org/pdf/2610.06031.pdf","url":"https://arxiv.org/abs/2610.06031","submittedDate":"2026-10-05","upvotes":0,"tags":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"announceDate":"2026-10-06","abstract":"Next-token prediction (NTP) is the standard pretraining objective for large language models, yet it provides an explicit training signal only for the immediate next token, which can lead models to exploit local patterns instead of capturing longer-range structure and ideas. Multi-token prediction (MTP) addresses this by training models to predict several future tokens. However, existing MTP methods often introduce a large number of new parameters with limited improvements in downstream performance. Latent MTP approaches address this efficiency issue by encoding future tokens into a vector representation. However, these approaches usually rely on external helper models for future token encoding. We propose LightMTP, a lightweight, i.e., parameter-efficient, latent MTP approach that bootstraps the future token representations from the model's own hidden states. Our two LightMTP variants ex"},{"arxiv":"https://arxiv.org/abs/2610.04605","topics":["Reasoning","Hallucination","Evaluation","Alignment","Interpretability"],"authors":["Yehonatan Elisha","Oren Barkan","Ziv Weiss Haddad","Noam Koenigstein"],"id":"arxiv:2610.04605","date":"2026-10-06","source":"arxiv","title":"ConEx: Human-Interpretable Saliency Maps via Concept-Aware Attribution","pdf":"https://arxiv.org/pdf/2610.04605.pdf","url":"https://arxiv.org/abs/2610.04605","submittedDate":"2026-10-03","upvotes":0,"tags":["Reasoning","Hallucination","Evaluation","Alignment","Interpretability"],"announceDate":"2026-10-06","abstract":"Many visual explanation methods in computer vision highlight pixel importance but struggle to link these low-level cues to semantically meaningful concepts, limiting their interpretability and trustworthiness. We introduce Concept-based Explanations (ConEx), a novel framework that bridges saliency visualization with concept-based reasoning to provide both faithfulness and interpretability. ConEx automatically discovers class-specific concepts and represents them through concept activation vectors (CAVs), learned without manual supervision using an architecture-specific masking mechanism that reduces noise introduced by the segmentation masks to enhance concept purity. ConEx generates faithful saliency maps that reveal where each concept appears in the image and how it contributes to the prediction. To evaluate the reliability of these learned concepts, we propose two complementary metric"},{"arxiv":"https://arxiv.org/abs/2610.06329","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning","RL for LLM"],"authors":["Chengbo Zang","Haoyu Dong","Mehmet Kerem Turkcan","Gil Zussman","Zoran Kostic","Javad Ghaderi"],"id":"arxiv:2610.06329","date":"2026-10-06","source":"arxiv","title":"Dynamic Minimax Regret Optimization for Robust LLM Post-Training","pdf":"https://arxiv.org/pdf/2610.06329.pdf","url":"https://arxiv.org/abs/2610.06329","submittedDate":"2026-10-05","upvotes":0,"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-06","abstract":"Modern LLM training increasingly relies on heterogeneous data sources spanning different domains, tasks, preference distributions, and difficulty levels. We study dynamic minimax regret for group-distributionally robust LLM post-training under instantaneous mini-batch-only bandit feedback. The framework views the training as a two-player sampler-optimizer process: a sampler adaptively selects among data sources using bandit feedback, while an optimizer updates the model parameters using stochastic gradients from the selected source. We focus on the practically restrictive setting where source losses evolve with model training but historical data are not re-evaluated, requiring the sampler to track instantaneous worst-sources from stale partial feedback. We propose DUCB-OGD, a simple and scalable algorithm that couples a Discounted Upper-Confidence-Bound sampler with an Online Gradient De"},{"arxiv":"https://arxiv.org/abs/2610.06293","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Qiutong Chen","Yuchan Guo","Zhenlong Yuan","Haobo Yang","Fangfang Lin","Xinyi Long","Yin Wang","Zijian Song","Rui Lan","Shi Qiu","Boyuan Pan","Yang Luo","Yuyin Zhou"],"id":"arxiv:2610.06293","date":"2026-10-06","source":"arxiv","title":"VepAgent: Bridging Causal-Transition via Tool-Augmented Reinforcement Learning for Video Event Prediction","pdf":"https://arxiv.org/pdf/2610.06293.pdf","url":"https://arxiv.org/abs/2610.06293","submittedDate":"2026-10-05","upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-06","abstract":"Multimodal Large Language Models (MLLMs) have demonstrated remarkable potential in video understanding, yet their reliance on retrospective summarization and text-centric priors often limits their ability to bridge unobserved causal transitions when applied to Video Event Prediction (VEP). To address this, we propose VepAgent, an agentic framework that integrates causal-transition reasoning with tool-augmented reinforcement learning (RL) for robust VEP. Unlike prior methods that passively project future trajectories from historical dependencies, our approach explicitly models the logical progression from terminal observed states to future events. Specifically, we first construct futurebench-4K, a high-quality chain-of-thought dataset for supervised fine-tuning (SFT) that effectively bridges the causal-logic gap by structuring the deduction of unobserved intermediate states. Subsequently,"},{"arxiv":"https://arxiv.org/abs/2610.05023","topics":["Post-Training","VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Uri Berger","Gal Chechik","Gal Dalal"],"id":"arxiv:2610.05023","date":"2026-10-06","source":"arxiv","title":"Look Where You Say You're Looking: Self-Grounded Attention for Visual Reasoning","pdf":"https://arxiv.org/pdf/2610.05023.pdf","url":"https://arxiv.org/abs/2610.05023","submittedDate":"2026-10-04","upvotes":0,"tags":["Post-Training","VLM Training","Reasoning","Evaluation","Alignment"],"announceDate":"2026-10-06","abstract":"We introduce Self-Saliency, a method for training Vision-Language Models (VLMs) to increase the alignment between their visual attention and the image regions mentioned in their reasoning. Self-Saliency uses a grounding model to localize the objects mentioned in each reasoning step and treats the resulting areas as supervision for the model's visual attention. Previous work on steering visual attention determines target image regions based solely on the image and question. In contrast, we show that conditioning the target regions on the model's generated reasoning improves downstream performance. For proper evaluation, we build a unified, broad suite of 25 visual reasoning benchmarks, where we reproduce the results of previous methods. We find that Self-Saliency significantly outperforms both prior attention-steering methods and baselines that ground image-level text, achieving both a be"}],"archive":[],"latestPath":"data/latest.json"};
